CREATE TABLE tags (
  slug TEXT PRIMARY KEY,
  name TEXT,                    -- display label; NULL falls back to the slug
  description TEXT NOT NULL,
  sort_order INTEGER,
  created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);

CREATE TABLE location_tags (
  location_id TEXT NOT NULL REFERENCES locations(id) ON DELETE CASCADE,
  tag_slug    TEXT NOT NULL REFERENCES tags(slug)    ON UPDATE CASCADE,
  PRIMARY KEY (location_id, tag_slug)
);

CREATE INDEX idx_location_tags_tag ON location_tags (tag_slug);

// GitHub answers 204 for yes and 404 for no.
// A broken or unauthorised credential answers 401 or 403.
if (res.status === 204) return 'yes';
if (res.status === 404) return 'no';

// 401/403/5xx: the question was not answered. Say so.
console.error(`collaborator check for ${login}: unexpected HTTP ${res.status}`);
if (res.status === 401) _resetTokenCache();
return 'error';
